 11	/**
 12	 * A graphical component that renders the simulation field.
 13	 */
 14	public class FieldView extends JPanel
 15	{
 16	    private static final int GRID_VIEW_SCALING_FACTOR = 6;
 17	
 18	    // Colors used for empty locations.
 19	    private static final Color EMPTY_COLOR = Color.white;
 20	    // Color used for objects that have no defined color.
 21	    private static final Color UNKNOWN_COLOR = Color.gray;
 22	    // Colour used for objects that are infected by disease.
 23	    private static final Color INFECTED_COLOR = Color.green;
 24	
 25	    private final int gridWidth;
 26	    private final int gridHeight;
 27	    private int xScale;
 28	    private int yScale;
 29	    private Dimension size;
 30	    private Graphics graphics;
 31	    private Image fieldImage;
 32	
 33	    // A map for storing colors for participants in the simulation.
 34	    private final Map<Class, Color> colors;
 35	
 36	    /**
 37	     * Create a new FieldView component.
 38	     */
 39	    public FieldView(int height, int width)
 40	    {
 41	        gridHeight = height;
 42	        gridWidth = width;
 43	        size = new Dimension(0, 0);
 44	        colors = new LinkedHashMap<>();
 45	    }
 46	
 47	    /**
 48	     * Define a color to be used for a given class of animal.
 49	     * @param animalClass The animal's Class object.
 50	     * @param color The color to be used for the given class.
 51	     */
 52	    public void setColor(Class animalClass, Color color)
 53	    {
 54	        colors.put(animalClass, color);
 55	    }
 56	
 57	    /**
 58	     * Render the current field contents.
 59	     * @param field The field whose contents should be drawn.
 60	     * @param weather The current weather state.
 61	     * @param stats Statistics to update while traversing the field.
 62	     */
 63	    public void render(Field field, Weather weather, FieldStats stats)
 64	    {
 65	        preparePaint();
 66	
 67	        for(int row = 0; row < field.getDepth(); row++) {
 68	            for(int col = 0; col < field.getWidth(); col++) {
 69	                Object creature = field.getObjectAt(row, col);
 70	                drawFieldLocation(col, row, creature, weather.getStormStart(), stats);
 71	            }
 72	        }
 73	
 74	        if(weather.getStormStart()) {
 75	            drawStormColor(field, weather);
 76	        }
 77	
 78	        repaint();
 79	    }
 80	
 81	    /**
 82	     * Tell the GUI manager how big we would like to be.
 83	     */
 84	    @Override
 85	    public Dimension getPreferredSize()
 86	    {
 87	        return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
 88	                             gridHeight * GRID_VIEW_SCALING_FACTOR);
 89	    }
 90	
 91	    /**
 92	     * Prepare for a new round of painting. Since the component
 93	     * may be resized, compute the scaling factor again.
 94	     */
 95	    private void preparePaint()
 96	    {
 97	        if(fieldImage == null || !size.equals(getSize())) {
 98	            size = getSize();
 99	            fieldImage = new BufferedImage(Math.max(1, size.width), Math.max(1, size.height),
100	                                           BufferedImage.TYPE_INT_RGB);
101	            graphics = fieldImage.getGraphics();
102	
103	            xScale = size.width / gridWidth;
104	            if(xScale < 1) {
105	                xScale = GRID_VIEW_SCALING_FACTOR;
106	            }
107	            yScale = size.height / gridHeight;
108	            if(yScale < 1) {
109	                yScale = GRID_VIEW_SCALING_FACTOR;
110	            }
111	        }
112	    }
113	
114	    /**
115	     * Draw a single field location and update population statistics.
116	     */
117	    private void drawFieldLocation(int col, int row, Object creature, boolean stormStarted, FieldStats stats)
118	    {
119	        if(creature == null) {
120	            drawMark(col, row, EMPTY_COLOR);
121	            return;
122	        }
123	
124	        stats.incrementCount(creature.getClass());
125	        if(!stormStarted && creature instanceof Animal) {
126	            Animal animal = (Animal) creature;
127	            if(animal.getIsInfected() && !animal.getIsImmuned()) {
128	                drawMark(col, row, INFECTED_COLOR);
129	                return;
130	            }
131	        }
132	
133	        drawMark(col, row, getColor(creature.getClass()));
134	    }
135	
136	    /**
137	     * Draw the colour of the storm.
138	     */
139	    private void drawStormColor(Field field, Weather weather)
140	    {
141	        List<Location> stormLocation =
142	            field.adjacentLocationsIncludingSelf(weather.getRandomLocation(), weather.getStormScope());
143	        for(Location location : stormLocation) {
144	            drawMark(location.getCol(), location.getRow(), getColor(Weather.class));
145	        }
146	    }
147	
148	    /**
149	     * @return The color to be used for a given class of animal.
150	     */
151	    private Color getColor(Class animalClass)
152	    {
153	        Color color = colors.get(animalClass);
154	        return color == null ? UNKNOWN_COLOR : color;
155	    }
156	
157	    /**
158	     * Paint one grid location on this field in a given color.
159	     */
160	    private void drawMark(int x, int y, Color color)
161	    {
162	        graphics.setColor(color);
163	        graphics.fillRect(x * xScale, y * yScale, xScale - 1, yScale - 1);
164	    }
165	
166	    /**
167	     * The field view component needs to be redisplayed. Copy the
168	     * internal image to screen.
169	     */
170	    @Override
171	    public void paintComponent(Graphics graphics)
172	    {
173	        super.paintComponent(graphics);
174	        if(fieldImage != null) {
175	            Dimension currentSize = getSize();
176	            if(size.equals(currentSize)) {
177	                graphics.drawImage(fieldImage, 0, 0, null);
178	            }
179	            else {
180	                // Rescale the previous image.
181	                graphics.drawImage(fieldImage, 0, 0, currentSize.width, currentSize.height, null);
182	            }
183	        }
184	    }
185	}

